"""Self-contained v3 desktop web console page.

The visual shell is the verified v2 console snapshot; v3-specific content
is limited to safe visible desktop automation settings and documentation.
"""

import base64
from pathlib import Path

from v3_version import VERSION


def _image_data_uri(relative_path: str, media_type: str) -> str:
    """Embed a release-owned help image without adding a public file route."""

    path = Path(__file__).resolve().parent / relative_path
    try:
        payload = base64.b64encode(path.read_bytes()).decode("ascii")
    except OSError:
        return ""
    return f"data:{media_type};base64,{payload}"

